import random
import balancer

random.seed(42)
for trial in range(300):
    n = random.randint(0, 40)
    items = []
    for _ in range(n):
        bid = random.choice(["a", "b", "c"])
        a = random.randint(0, 10**9)
        z = min(a + random.randint(1, 100), 10**9)
        items.append({"id": bid, "k": "S", "a": a, "z": z, "v": 1})
    # reference: old per-group stable comparison sort
    grouped = {}
    for it in items:
        grouped.setdefault(it["id"], []).append((it["k"], it["a"], it["z"], it["v"]))
    try:
        ref = {}
        for bid, segs in grouped.items():
            segs = sorted(segs, key=lambda s: s[1])
            for i in range(len(segs) - 1):
                if segs[i][2] > segs[i+1][1]:
                    raise ValueError("overlap")
            ref[bid] = segs
        ref_ok = True
    except ValueError:
        ref_ok = False
    try:
        got = balancer.parse_config_faults(
            [{"id": it["id"], "k": it["k"], "a": it["a"], "z": it["z"], "v": it["v"]}
             for it in items])
        got_ok = True
    except balancer._Failure:
        got_ok = False
    assert got_ok == ref_ok, (trial, "accept mismatch")
    if got_ok:
        assert list(got) == list(ref), (trial, "key order mismatch")
        for bid in ref:
            assert got[bid] == [tuple(s) for s in ref[bid]], (trial, bid)
print("300 randomized trials: radix normalization identical to comparison sort")
EOF

